/// <summary>
/// A stone crypt (door faces -Z) with grave markers before it. variant 1: a barrow, an earthen mound ringed with kerb
/// stones, the slab that sealed its black doorway thrown down in front.
/// </summary>
void Crypt(Transform t, int variant = 0)
{
    var stone = Tint(art.stone, new Color(.36f, .36f, .37f));
    // Local height of the ground at a local spot, so stones round the foot sit on rolling land.
    float Foot(float lx, float lz) { var at = t.TransformPoint(new Vector3(lx, 0, lz)); return (HeightAt(at.x, at.z) - t.position.y) / t.lossyScale.y; }
    if (variant == 1)
    {
        float e = Foot(0, -2.6f);
        Part(PrimitiveType.Sphere, t, new Vector3(0, -.2f, 2.2f), new Vector3(7.4f, 5.8f, 8.6f), Tint(art.foliage, new Color(.3f, .31f, .19f)));
        Part(PrimitiveType.Cube, t, new Vector3(0, e + 1.05f, -2.15f), new Vector3(1.6f, 2.2f, .1f), Tint(art.metal, new Color(.04f, .04f, .05f)));
        foreach (int s in new[] { -1, 1 }) Part(PrimitiveType.Cube, t, new Vector3(s * 1.05f, e + 1.1f, -2.2f), new Vector3(.5f, 2.3f, .6f), stone);
        Part(PrimitiveType.Cube, t, new Vector3(0, e + 2.4f, -2.2f), new Vector3(2.9f, .45f, .8f), stone);
        Part(PrimitiveType.Cube, t, new Vector3(0, e - .1f, -2.9f), new Vector3(2.6f, .4f, 1.2f), stone);
        Part(PrimitiveType.Cube, t, new Vector3(1.9f, e - .02f, -3.3f), new Vector3(1.6f, .36f, 2.1f), stone, Quaternion.Euler(0, 20, 0));
        for (int i = 0; i < 9; i++)
        {
            float a = 40 + i * 35, kx = Mathf.Sin(a * Mathf.Deg2Rad) * 3.9f, kz = 2.2f - Mathf.Cos(a * Mathf.Deg2Rad) * 4.5f;
            Part(PrimitiveType.Cube, t, new Vector3(kx, Foot(kx, kz) + .2f, kz), new Vector3(.7f, .55f, .45f), stone, Quaternion.Euler(0, -a, (i % 3 - 1) * 5));
        }
    }
    else
    {
        Part(PrimitiveType.Cube, t, new Vector3(0, 1.2f, 1.5f), new Vector3(6, 2.4f, 6), stone);
        MeshPart(ZoneMeshes.GableRoof(6.6f, 6.6f, 1.6f), t, new Vector3(0, 2.4f, 1.5f), Tint(art.slate, new Color(.27f, .28f, .3f)));
        Part(PrimitiveType.Cube, t, new Vector3(0, 1, -1.52f), new Vector3(1.8f, 2, .1f), Tint(art.metal, new Color(.14f, .14f, .16f)));
        foreach (int s in new[] { -1, 1 }) Part(PrimitiveType.Cube, t, new Vector3(s * 1.4f, 1.3f, -1.7f), new Vector3(.6f, 2.6f, .6f), stone);
        for (int i = 0; i < 3; i++) Part(PrimitiveType.Cube, t, new Vector3(0, .1f + i * .12f, -2.6f + i * .35f), new Vector3(2.6f, .2f, .4f), stone);
    }
    // Grave markers before it (same five draws each, in the same order), set on the ground where they stand.
    for (int i = 0; i < 6; i++) { float gx = R01 * 10 - 5, gz = -4 - R01 * 4; Part(PrimitiveType.Cube, t, new Vector3(gx, Foot(gx, gz) + .46f, gz), new Vector3(.55f, 1, .15f), stone, Quaternion.Euler(R01 * 10 - 5, R01 * 30 - 15, R01 * 10 - 5)); }
    if (variant == 1) Solid(t, new Vector3(0, 1.2f, 2.2f), new Vector3(6.8f, 2.4f, 8)); else Solid(t, new Vector3(0, 1.8f, 1.2f), new Vector3(6.2f, 3.6f, 6.6f));
}

